/* @autogenerated */
package net.civeira.phylax.bootstrap.install;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.infrastructure.migration.MigrationSeed;
import net.civeira.phylax.feature.observe.config.ObservabilitySettings;
import net.civeira.phylax.feature.observe.config.ObserveDefaults;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfigChangeSet;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.gateway.ObservabilityConfigCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.gateway.ObservabilityConfigFilter;

/**
 * Creates the row {@code default} of observability-config with the defaults of
 * config/observability.yaml ({@code app.observe.defaults.*}). Every value is set explicitly: the
 * defaults of the model are not applied when a row is created. It runs once; if the row already
 * exists (an installation restored from a backup) it is kept.
 */
@ApplicationScoped
@RequiredArgsConstructor
@Slf4j
public class InstallObservabilityConfig implements MigrationSeed {

  private final ObservabilityConfigCommandRepositoryGateway configs;
  private final ObserveDefaults defaults;

  @Override
  public String id() {
    return "seed/install-observability-config";
  }

  @Override
  public int order() {
    return 15;
  }

  @Override
  @Transactional
  public void run() {
    if (configs.find(ObservabilityConfigFilter.builder().code(ObservabilitySettings.CODE).build())
        .isPresent()) {
      return;
    }
    ObservabilityConfigChangeSet change = new ObservabilityConfigChangeSet().newUid()
        .code(ObservabilitySettings.CODE).retentionDaysLogs(defaults.getRetentionDaysLogs())
        .retentionDaysTraces(defaults.getRetentionDaysTraces())
        .retentionDaysErrors(defaults.getRetentionDaysErrors())
        .retentionDaysMetrics(defaults.getRetentionDaysMetrics())
        .retentionDaysMetricsRollup(defaults.getRetentionDaysMetricsRollup())
        .maxDiskMb(defaults.getMaxDiskMb()).scrubFields(defaults.getScrubFields())
        .labelDenylist(defaults.getLabelDenylist())
        .captureRequestBody(defaults.isCaptureRequestBody());
    configs.create(ObservabilityConfig.create(change));
    log.info("Created the observability configuration '{}'", ObservabilitySettings.CODE);
  }
}
